#[cfg(test)]
mod arabic_tests {
    use super::*;
    #[test]
    fn arabic_covers_registered_effects_and_parameter_labels() {
        let c = catalog("ar").unwrap();
        let mut missing = Vec::new();
        for effect in effectcraft_engine::effects::registry() {
            for key in [effect.name, effect.category].into_iter().chain(effect.params.iter().map(|p| p.name)) {
                if !c.contains_key(key) {
                    missing.push(key.to_string());
                }
            }
            for parameter in effect.params.iter() {
                if let effectcraft_project::ParamUi::Popup { options } = &parameter.ui {
                    for key in options {
                        if !c.contains_key(key.as_str()) {
                            missing.push(key.clone());
                        }
                    }
                }
            }
        }
        use effectcraft_engine::effects::{PARAM_GROUPS, keylight, roto, warp_stab};
        for (_, key) in warp_stab::GROUPS.iter().chain(roto::GROUPS).chain(keylight::GROUPS).chain(PARAM_GROUPS) {
            if !c.contains_key(key) {
                missing.push(key.to_string());
            }
        }
        for (_, key) in effectcraft_engine::text_presets() {
            if !c.contains_key(key.as_str()) {
                missing.push(key);
            }
        }
        for (_, name, category) in effectcraft_engine::animation_presets() {
            for key in [name, category] {
                if !c.contains_key(key.as_str()) {
                    missing.push(key);
                }
            }
        }
        for rows in [JAPANESE, SIMPLIFIED_CHINESE, TRADITIONAL_CHINESE, UKRAINIAN, PORTUGUESE, CZECH] {
            for (key, _) in rows {
                if !c.contains_key(key) {
                    missing.push(key.to_string());
                }
            }
        }
        missing.sort();
        missing.dedup();
        assert!(missing.is_empty(), "untranslated registered labels: {missing:#?}");
    }

    #[test]
    fn arabic_has_logical_order_and_preserves_values() {
        set_current("ar");
        assert_eq!(tr("Composition Name:"), "اسم التركيب:");
        assert_eq!(tr_args("Step {} of {}: {}", &[&1, &3, &"clip 12.mp4"]), "الخطوة 1 من 3: clip 12.mp4");
        assert_eq!(tr("my original.mp4"), "my original.mp4");
        for (source, value) in ARABIC {
            assert_eq!(source.matches("{}").count(), value.matches("{}").count(), "{source}");
        }
        set_current("en");
        assert_eq!(tr("Composition Name:"), "Composition Name:");
    }
}
